#include "stdlib/blas/ext/base/ndarray/dcusumkbn.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <sys/time.h>

#define NAME "dcusumkbn"
#define ITERATIONS 1000
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Runs a benchmark and validates the final cumulative sum.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds or -1 on failure
*/
static double benchmark( const int iterations, const int len ) {
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;
	int64_t shape[] = { len };
	int64_t strides[] = { STDLIB_NDARRAY_FLOAT64_BYTES_PER_ELEMENT };
	int64_t scalarStrides[] = { 0 };
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	double dataInitial[] = { 0.0 };
	double elapsed = -1.0;
	double t;
	int i;

	double *dataX = (double *)malloc( (size_t)len * sizeof( double ) );
	double *dataY = (double *)malloc( (size_t)len * sizeof( double ) );
	if ( dataX == NULL || dataY == NULL ) {
		fprintf( stderr, "Error allocating data buffers.\n" );
		free( dataX );
		free( dataY );
		return elapsed;
	}
	for ( i = 0; i < len; i++ ) {
		dataX[ i ] = 1.0;
		dataY[ i ] = 0.0;
	}

	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataX, 1, shape, strides, 0, order, imode, 1, submodes );
	// cppcheck-suppress invalidPointerCast
	struct ndarray *y = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataY, 1, shape, strides, 0, order, imode, 1, submodes );
	// cppcheck-suppress invalidPointerCast
	struct ndarray *initial = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT64, (uint8_t *)dataInitial, 0, NULL, scalarStrides, 0, order, imode, 1, submodes );
	if ( x == NULL || y == NULL || initial == NULL ) {
		fprintf( stderr, "Error allocating ndarray descriptors.\n" );
	} else {
		const struct ndarray *arrays[] = { x, y, initial };
		t = tic();
		for ( i = 0; i < iterations; i++ ) {
			stdlib_blas_ext_dcusumkbn( arrays );
		}
		elapsed = tic() - t;
		if ( dataY[ 0 ] != 1.0 || dataY[ len-1 ] != (double)len ) {
			fprintf( stderr, "Unexpected cumulative sum.\n" );
			elapsed = -1.0;
		}
	}

	// Free descriptors before releasing their backing buffers:
	if ( x != NULL ) {
		stdlib_ndarray_free( x );
	}
	if ( y != NULL ) {
		stdlib_ndarray_free( y );
	}
	if ( initial != NULL ) {
		stdlib_ndarray_free( initial );
	}
	free( dataX );
	free( dataY );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const int lengths[] = { 16, 1024 };
	double elapsed;
	int passing = 0;
	int count = 0;
	int i;
	int j;

	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, lengths[ i ] );
			elapsed = benchmark( ITERATIONS, lengths[ i ] );
			if ( elapsed < 0.0 ) {
				printf( "not ok %d benchmark failed\n", count );
			} else {
				printf( "  ---\n" );
				printf( "  iterations: %d\n", ITERATIONS );
				printf( "  elapsed: %0.9f\n", elapsed );
				printf( "  ...\n" );
				printf( "ok %d benchmark finished\n", count );
				passing += 1;
			}
		}
	}
	printf( "#\n" );
	printf( "1..%d\n", count );
	printf( "# total %d\n", count );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	if ( passing == count ) {
		printf( "# ok\n" );
		return EXIT_SUCCESS;
	}
	return EXIT_FAILURE;
}
